<?php

namespace App\Http\Controllers\Api;

// REST API endpoint that returns gift suggestions for a cart, generated by the LLM provider from the cart's items.

use App\Http\Controllers\Controller;
use App\Models\Cart;
use App\Services\GiftSuggestionService;
use App\Exceptions\LlmUnavailableException;
use Illuminate\Http\JsonResponse;
use Illuminate\Support\Facades\Log;

class GiftSuggestionController extends Controller
{
    public function show(Cart $cart, GiftSuggestionService $service): JsonResponse
    {
        try {
            return response()->json([
                'data' => [
                    'cart_id' => $cart->id,
                    'suggestions' => $service->suggest($cart),
                ],
            ]);
        } catch (LlmUnavailableException $exception) {
            Log::warning('Gift suggestions unavailable', [
                'cart_id' => $cart->id,
                'error' => $exception->getMessage(),
            ]);

            return response()->json([
                'message' => 'Gift suggestions are temporarily unavailable.',
                'data' => [
                    'cart_id' => $cart->id,
                ],
            ], 503);
        }
    }
}